    if not stripped.startswith("```"):
        return stripped
    first_break = stripped.find("\n")
    if first_break < 0:
        return stripped
    tail = stripped.rstrip()
    if not tail.endswith("```"):
        return stripped
    return tail[first_break + 1:-3].strip()

