        row = copy.deepcopy(dict(action))
        key = row.get("idempotency_key")
        if isinstance(key, str):
            names.setdefault(key, f"K{len(names)}")
            row["idempotency_key"] = names[key]
        rows.append(row)
    return tuple(rows)

